import { Config } from "sst/node/config";

export const ALD_MAIL_MARKETS = ["DE", "FR"];
export type AldMailMarket = (typeof ALD_MAIL_MARKETS)[number];

export enum EmailTemplate {
  ALD_HANDOVER_DOCUMENT = "ALD_HANDOVER_DOCUMENT",
  ALD_INVOICE_DOCUMENT = "ALD_INVOICE_DOCUMENT",
  SUPPORT_FAULTY_PAYLOAD = "SUPPORT_FAULTY_PAYLOAD",
  SUPPORT_INVOICE_NOT_FOUND = "SUPPORT_INVOICE_NOT_FOUND",
}

export const SUBJECTS: Record<EmailTemplate, Record<string, string>> = {
  ALD_HANDOVER_DOCUMENT: {
    FR: "Smart Europe GmbH: Document: {{filename}} (Numéro de contrat de leasing: {{leasingContractNumber}}, VIN: {{vin}})",
    DE: "Smart Europe GmbH: Dokument: {{filename}} (Leasingvertragsnummer: {{leasingContractNumber}}, VIN: {{vin}})",
    CH: "Smart Europe GmbH: Dokument: {{filename}} (Leasingvertragsnummer: {{leasingContractNumber}}, VIN: {{vin}})",
  },
  ALD_INVOICE_DOCUMENT: {
    FR: "Smart Europe GmbH: Document: {{filename}} (Numéro de facture: {{invoiceNumber}}, Numéro de contrat de leasing: {{leasingContractNumber}}, VIN: {{vin}})",
    DE: "Smart Europe GmbH: Dokument: {{filename}} (Rechnungsnummer: {{invoiceNumber}}, Leasingvertragsnummer: {{leasingContractNumber}}, VIN: {{vin}})",
    CH: "Smart Europe GmbH: Dokument: {{filename}} (Rechnungsnummer: {{invoiceNumber}}, Leasingvertragsnummer: {{leasingContractNumber}}, VIN: {{vin}})",
  },

  SUPPORT_FAULTY_PAYLOAD: {
    default: "Critical error: current document could not get generated for customer!",
  },
  SUPPORT_INVOICE_NOT_FOUND: {
    default: "Error: corresponding invoice for ALD API transfer takes too long",
  },
};

export const getEmailDomain = () => {
  if (Config.STAGE === "prod") return "docs.smart.com";
  if (Config.STAGE === "stage") return "docs-stage.srv.smart.com";

  return "docs-dev.srv.smart.com";
};

export const getInternalEmail = () => {
  if (Config.STAGE === "prod") 
    return [
      ...(Config.DMP_ARCHIVE_EMAIL?.split(",").filter(Boolean) ?? []),
      "dmp-archive@dev.smart.com",
    ];

  if (Config.STAGE === "stage") 
    return [
      ...(Config.DMP_ARCHIVE_EMAIL?.split(",").filter(Boolean) ?? []),
      "dmp-archive-stage@dev.smart.com",
    ];
  return [
    ...(Config.DMP_ARCHIVE_EMAIL?.split(",").filter(Boolean) ?? []),
    "dmp-archive-dev@dev.smart.com",
  ];
};

export const SENDERS = {
  ALD: `ald@${getEmailDomain()}`,
  SMART_INTERNAL: `no-reply@${getEmailDomain()}`,
};

export const RECEIVERS: Record<EmailTemplate, Record<string, string>> = {
  ALD_HANDOVER_DOCUMENT: {
    FR: "facturevnpdfmail.frrestm@ayvens.com",
    DE: "disposition.smart@aldautomotive.com",
    CH: "purchase.ch@aldautomotive.com",
  },
  ALD_INVOICE_DOCUMENT: {
    FR: "facturevnpdfmail.frrestm@ayvens.com",
    DE: "neufahrzeugrechnung@aldautomotive.com",
    CH: "purchase.ch@aldautomotive.com",
  },
  SUPPORT_FAULTY_PAYLOAD: {
    default: "eu.itoperations@smart.com",
  },
  SUPPORT_INVOICE_NOT_FOUND: {
    default: "eu.itoperations@smart.com",
  },
};

export const HIDDEN_RECEIVERS: Record<EmailTemplate, Record<string, string[]>> = {
  ALD_HANDOVER_DOCUMENT: {
    FR: [
      "linda.boucher@ayvens.com",
    ],
