import { Config } from "sst/node/config";
import { NotFound, UnsupportedMarket } from "../../common";
import { formKiQ } from "../../data/FormKiQ";
import { ALD_MAIL_MARKETS, EmailTemplate, getInternalEmail, SUBJECTS } from "./constants";
import { Attachment, SendEmailRequestWithAttachments } from "./schema";

const fetchHtmlTemplate = async (template: string): Promise<string> => {
  const path = `email-templates/${template}.html`;

  const search = await formKiQ.search.byPath(path, undefined);

  const documentId = search.documents[0].documentId;

  if (!documentId) {
    throw new NotFound(`Template not found for path: ${path}`);
  }

  const documentContent = await formKiQ.documents.getDocumentContent(documentId);

  return documentContent.content;
};

export const createHtmlEmailContent = async (
  template: string,
  placeholders?: Record<string, string>,
): Promise<string> => {
  let htmlContent = await fetchHtmlTemplate(template);

  if (!placeholders) {
    return htmlContent;
  }

  Object.keys(placeholders).forEach((key) => {
    htmlContent = htmlContent.replace(new RegExp(`{{${key}}}`, "g"), placeholders![key]);
  });

  return htmlContent;
};

export const createEmailSubject = (template: EmailTemplate, market: string, placeholders?: Record<string, string>) => {
  let subject = SUBJECTS[template][market];

  if (!subject) {
    throw new NotFound(`Subject template ${template} not found`);
  }

  if (!placeholders) {
    return subject;
  }

  Object.keys(placeholders).forEach((key) => {
    subject = subject.replace(new RegExp(`{{${key}}}`, "g"), placeholders![key]);
  });

  return subject;
};

export const ensureAndValiteAldMailMarket = (market: string): string => {
  market = market.toUpperCase();

  if (ALD_MAIL_MARKETS.includes(market)) return market;

  throw new UnsupportedMarket(`Invalid market: ${market}`);
};

export const createEmailRequest = (
  from: string,
  to: string,
  subject: string,
  htmlContent: string,
  attachments?: Attachment[],
  bcc?: string[],
): SendEmailRequestWithAttachments => {
  const internalEmail = getInternalEmail();
  const stage = Config.STAGE;

  if (stage !== "prod") {
    to = internalEmail;
  }

  return {
    from: {
      email: from,
    },
    to: {
      to: [to],
      bcc: (stage === "prod" ? [internalEmail] : []).concat(bcc ?? []),
    },
    content: {
      subject: subject,
      html: htmlContent,
      encoding: "utf-8",
    },
    attachments: attachments,
  };
};

export const createEmailRequestWithMultipleRecipients = (
  from: string,
  to: string[],
  subject: string,
  htmlContent: string,
  attachments?: Attachment[],
  bcc?: string[],
): SendEmailRequestWithAttachments => {
  const internalEmail = getInternalEmail();
  const stage = Config.STAGE;

  const toRecipients = stage !== "prod" ? [internalEmail] : to;

  return {
    from: {
      email: from,
    },
    to: {
      to: toRecipients,
      bcc: (stage === "prod" ? [internalEmail] : []).concat(bcc ?? []),
    },
    content: {
      subject: subject,
      html: htmlContent,
      encoding: "utf-8",
    },
    attachments: attachments,
  };
};

export const onlyInProd = <T>(input: T, defaultVal: T): T => {
  if ("prod" === Config.STAGE) {
    return input;
  }
  return defaultVal;
};

