//Customer IDs that belong to ALD. They are defined in ERP (SAP S/4HANA). We use them to determine if an invoice
// belongs to ALD and should thus be sent to ALD/Ayven.
import { logger } from "@dmp-integration-gateway/core/common/logger";
import { Config } from "sst/node/config";

export const aldCustomerIds = [
  "4000003322",
  "4000001371",
  "4000001800",
  "4000002028",
  "4000002153",
  "4000002408",
  "4000003480",
  "4000001746",
];

export const isAldCustomer = (customerId: string): boolean => {
  const configAldIds =
    Config.ALD_CUSTOMER_IDS?.split(",").filter(Boolean) || [];

  logger.info("Convert customer", { 
    ConfigALD_CUSTOMER_IDS:Config.ALD_CUSTOMER_IDS, 
    AllAldCustomerIds:[...configAldIds, ...aldCustomerIds], 
    IncludedInAllAldCustomerIds: [...configAldIds, ...aldCustomerIds].includes(customerId) });

  return [...configAldIds, ...aldCustomerIds].includes(customerId);
};

